def rule_v2(g, bg, thresh=4):
    Hh,W=len(g),len(g[0])
    marks=[(r,c) for r in range(Hh) for c in range(W) if g[r][c]!=bg]
    rs=[r for r,_ in marks]; cs=[c for _,c in marks]
    r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
    ob=lambda r,c: r in (r0,r1) or c in (c0,c1)
    cand=[row[:] for row in g]
    active=set(marks)
    # border fill (all gaps) + collect border fills as anchors
    for r in range(r0,r1+1):
        for c in range(c0,c1+1):
            if ob(r,c) and g[r][c]==bg:
                cand[r][c]=2; active.add((r,c))
    rows_m={}; cols_m={}
    for r,c in active: (rows_m.setdefault(r,[]) if True else None); rows_m[r]=rows_m.get(r,[])+[c]
    for r,c in active: cols_m.setdefault(c,[]).append(r)
    for d,isrow in [(rows_m,True),(cols_m,False)]:
        for k,v in d.items():
            v=sorted(v)
            if isrow and k in (r0,r1): continue
            if (not isrow) and k in (c0,c1): continue
            if len(v)<thresh: continue
            for a,b in zip(v,v[1:]):
                if b-a<=2:
                    for x in range(a+1,b):
                        rr,cc=(k,x) if isrow else (x,k)
                        if g[rr][cc]==bg: cand[rr][cc]=2
    return cand
